<?php declare(strict_types=1);
$invoicePage=(new \Kulturhus\Verein\OutgoingInvoiceCatalogue($db,(string)$_SESSION['actor']))->nativePage($_GET);$c=$invoicePage['controls'];$route=['view'=>'finance','tab'=>'outgoing']+array_diff_key($c,['invoices_page'=>true]);
if($invoicePage['error']!==''&&http_response_code()<400)http_response_code(422);
?>
<link rel="stylesheet" href="general-settings-native.css?v=3"><link rel="stylesheet" href="outgoing-invoice-native.css?v=1">
<div class="general-settings-native invoice-catalogue" data-outgoinginvoice-catalogue>
<form method="get" class="general-settings-page-form" novalidate><?=hidden('view','finance').hidden('tab','outgoing').hidden('invoices_page','1')?>
<label><?=e($oit('Nummer, Empfänger oder Beschreibung'))?><?php if(strpbrk($c['invoices_q'],"\r\n")!==false): ?><textarea class="form-control" name="invoices_q"><?= "\n".e($c['invoices_q']) ?></textarea><?php else: ?><input class="form-control" name="invoices_q" value="<?=e($c['invoices_q'])?>"><?php endif ?></label>
<?php foreach(['inv_status'=>['Stand',$labels],'inv_kind'=>['Art',$invoiceKinds]]as$key=>[$label,$choices]): ?><label><?=e($oit($label))?><select class="form-control" name="<?=e($key)?>"><option value=""><?=e($oit('Alle'))?></option><?php if($c[$key]!==''&&!isset($choices[$c[$key]])): ?><option selected value="<?=e($c[$key])?>"><?=e($oit('Ursprüngliche unbekannte Auswahl').': '.$c[$key])?></option><?php endif ?><?php foreach($choices as$value=>$text): ?><option value="<?=e($value)?>"<?=$c[$key]===$value?' selected':''?>><?=e($text)?></option><?php endforeach ?></select></label><?php endforeach ?>
<button class="btn btn-solid theme-primary"><?=e($oit('Ganze Rechnungssuche öffnen'))?></button></form>
<?php if($invoicePage['error']!==''): ?><p role="alert"><?=e($oit($invoicePage['error']))?></p><?php endif ?>
<?php if($invoicePage['total']!==null): ?><p><?=e(strtr($oit('{count} Rechnungsdokumente'),['{count}'=>(string)$invoicePage['total']]))?><?php if($invoicePage['page']!==null): ?> · <?=e(strtr($oit('Seite {page} von {pages}'),['{page}'=>(string)$invoicePage['page'],'{pages}'=>(string)$invoicePage['pages']]))?><?php endif ?></p><?php endif ?>
<div class="invoice-cards"><?php foreach($invoicePage['rows']as$row): ?><article class="card invoice-summary" data-invoice-summary data-outgoing-invoice-id="<?=e($row['id'])?>"><h3><?=e($row['number']?:$oit('Noch ohne Nummer'))?></h3><p><strong><?=e($row['buyer_name'])?></strong></p><p><?=e($row['description'])?></p><p><?=e($invoiceKinds[$row['kind']].' · '.$labels[$row['state']])?></p><p><?=e(dateDe($row['document_date']))?> · <?=e(euro((int)$row['total_cents']))?> <?=e($oit('brutto'))?></p><?php $oiPaymentFacts=$row['payment'];$oiPaymentId=$row['id'];$oiPaymentKind=$row['kind'];require __DIR__.'/outgoing-invoice-payment.php'; ?><a class="btn btn-outline theme-secondary" href="<?=e(url($route+['invoices_page'=>$c['invoices_page'],'invoice'=>$row['id']]))?>"><?=e($oit('Dokument öffnen'))?></a></article><?php endforeach ?></div>
<?php if(!$invoicePage['rows']&&$invoicePage['error']===''): ?><p><?=e($oit('Keine passenden Rechnungsdokumente.'))?></p><?php endif ?>
<?php if($invoicePage['page']!==null&&$invoicePage['pages']>1): ?><nav class="general-settings-actions" aria-label="<?=e($oit('Rechnungsseiten'))?>"><?php if($invoicePage['page']>1): ?><a class="btn btn-outline theme-secondary" href="<?=e(url($route+['invoices_page'=>(string)($invoicePage['page']-1)]))?>"><?=e($oit('Vorherige Seite'))?></a><?php endif ?><?php if($invoicePage['page']<$invoicePage['pages']): ?><a class="btn btn-outline theme-secondary" href="<?=e(url($route+['invoices_page'=>(string)($invoicePage['page']+1)]))?>"><?=e($oit('Nächste Seite'))?></a><?php endif ?></nav><?php endif ?>
<form method="get" class="general-settings-page-form" novalidate><?php foreach($route as$key=>$value)echo hidden($key,$value); ?><label><?=e($oit('Rechnungsseite'))?><input class="form-control" name="invoices_page" inputmode="numeric" value="<?=e($c['invoices_page'])?>"></label><button class="btn btn-outline theme-secondary"><?=e($oit('Genau diese Rechnungsseite öffnen'))?></button></form>
</div>
